//! Consume the independent decimal special-function vectors as a QA gate.
//!
//! This binary deliberately does not compare a solver against the same Rust
//! analytical implementation.  The expected values are generated by the
//! checked-in Python `decimal` script in `sonium-wave` at 100 digits.

use serde::Deserialize;
use sonium_qa::QaResult;
use sonium_wave::special::{
    associated_legendre, legendre_polynomials, legendre_polynomials_derivative, spherical_bessel_j,
    spherical_bessel_j_derivative, spherical_bessel_y, spherical_bessel_y_derivative,
};

const FIXTURE: &str = include_str!("../../sonium-wave/fixtures/special-golden-v1.json");
const TOLERANCE: f64 = 5e-13;

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    precision_digits: u32,
    generator: String,
    spherical: Vec<SphericalCase>,
    legendre: Vec<LegendreCase>,
}

#[derive(Debug, Deserialize)]
struct SphericalCase {
    x: String,
    j: Vec<String>,
    y: Vec<String>,
    j_derivative: Vec<String>,
    y_derivative: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct LegendreCase {
    x: String,
    p: Vec<String>,
    derivative: Vec<String>,
    associated_m: usize,
    associated: Vec<String>,
}

fn max_relative_error(actual: &[f64], expected: &[String]) -> Result<f64, String> {
    if actual.len() != expected.len() {
        return Err(format!(
            "vector length mismatch: actual {}, expected {}",
            actual.len(),
            expected.len()
        ));
    }
    actual.iter().zip(expected).enumerate().try_fold(
        0.0_f64,
        |maximum, (index, (actual, expected))| {
            let expected = expected
                .parse::<f64>()
                .map_err(|error| format!("fixture value {index} is not decimal: {error}"))?;
            if !actual.is_finite() || !expected.is_finite() {
                return Err(format!("non-finite value at index {index}"));
            }
            let error = (actual - expected).abs() / expected.abs().max(1.0);
            Ok(maximum.max(error))
        },
    )
}

fn run() -> Result<(f64, f64), String> {
    let fixture: Fixture = serde_json::from_str(FIXTURE)
        .map_err(|error| format!("special golden fixture is invalid JSON: {error}"))?;
    if fixture.schema != "sonium-wave.special-golden.v1" {
        return Err(format!("unexpected fixture schema {}", fixture.schema));
    }
    if fixture.precision_digits < 100 {
        return Err("fixture precision must be at least 100 decimal digits".to_owned());
    }
    if !fixture.generator.contains("Python decimal") {
        return Err("fixture provenance does not identify the decimal generator".to_owned());
    }

    let mut spherical_max: f64 = 0.0;
    for case in &fixture.spherical {
        let x = case
            .x
            .parse::<f64>()
            .map_err(|error| format!("spherical argument is not decimal: {error}"))?;
        for (actual, expected) in [
            (spherical_bessel_j(case.j.len(), x), &case.j),
            (spherical_bessel_y(case.y.len(), x), &case.y),
            (
                spherical_bessel_j_derivative(case.j_derivative.len(), x),
                &case.j_derivative,
            ),
            (
                spherical_bessel_y_derivative(case.y_derivative.len(), x),
                &case.y_derivative,
            ),
        ] {
            spherical_max = spherical_max.max(max_relative_error(&actual, expected)?);
        }
    }

    let mut legendre_max: f64 = 0.0;
    for case in &fixture.legendre {
        let x = case
            .x
            .parse::<f64>()
            .map_err(|error| format!("Legendre argument is not decimal: {error}"))?;
        legendre_max = legendre_max.max(max_relative_error(
            &legendre_polynomials(case.p.len(), x),
            &case.p,
        )?);
        legendre_max = legendre_max.max(max_relative_error(
            &legendre_polynomials_derivative(case.derivative.len(), x),
            &case.derivative,
        )?);
        legendre_max = legendre_max.max(max_relative_error(
            &associated_legendre(
                case.associated.len() + case.associated_m - 1,
                case.associated_m,
                x,
            ),
            &case.associated,
        )?);
    }

    if spherical_max > TOLERANCE || legendre_max > TOLERANCE {
        return Err(format!(
            "golden-vector tolerance exceeded: spherical={spherical_max:.3e}, legendre={legendre_max:.3e}, tolerance={TOLERANCE:.3e}"
        ));
    }
    Ok((spherical_max, legendre_max))
}

fn main() {
    match run() {
        Ok((spherical_max, legendre_max)) => {
            let record = QaResult::passed("wave.special-golden.v1")
                .requested_backend("cpu")
                .actual_backend("cpu")
                .metric("spherical_max_relative_error", spherical_max)
                .metric("legendre_max_relative_error", legendre_max)
                .metric("decimal_precision_digits", 100.0)
                .to_json_line()
                .expect("special golden QA result must serialize");
            println!("QA_RESULT: {record}");
            println!("SUCCESS");
        }
        Err(error) => {
            let record = QaResult::failed("wave.special-golden.v1", error)
                .to_json_line()
                .expect("special golden QA failure result must serialize");
            println!("QA_RESULT: {record}");
            println!("FAILED");
            std::process::exit(1);
        }
    }
}
